import { useRouter } from "expo-router";
import { Button } from "react-native";

type Props = { plantId: string; nickname: string };
export function OpenPlantButton({ plantId, nickname }: Props) {
  const router = useRouter();
  return (
    <Button title={`Open ${nickname}`} onPress={() => {
      router.push({
        pathname: "/plants/[plantId]",
        params: { plantId },
      });
    }} />
  );
}

import { Id } from "@plantopedia/contracts";
import { useLocalSearchParams, useRouter } from "expo-router";
import { Button, Text, View } from "react-native";

export default function PlantIdentityScreen() {
  const { plantId } = useLocalSearchParams<{
    plantId?: string | string[];
  }>();
  const router = useRouter();
  const parsed = Id.safeParse(plantId);
  function leave() {
    if (router.canGoBack()) router.back();
    else router.replace("/plants");
  }
  return (
    <View style={{ padding: 24, gap: 16 }}>
      <Text>{parsed.success
        ? `Specimen ID: ${parsed.data}`
        : "This plant link is not valid."}</Text>
      <Button title="Back to your garden" onPress={leave} />
    </View>
  );
}
